 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
     for (int b = 0; b < 256; ++b) hist[b] = 0;
+#if defined(__ARM_NEON)
+    // 8 sub-histograms to break hot-bin store-to-load dependencies
+    static constexpr size_t SUB_COUNT = 16;
+    static uint32_t sub_hist[SUB_COUNT][256];
+    for (size_t s = 0; s < SUB_COUNT; ++s) {
+        for (int b = 0; b < 256; ++b) sub_hist[s][b] = 0;
+    }
+#endif
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    // Process 8 elements per iteration with NEON vectorization
+    const size_t CHUNK = 16;
+    for (size_t i = 0; i < n; i += CHUNK) {
+        size_t end = std::min(i + CHUNK, n);
+        for (size_t k = 0; k < (end - i); ++k) {
+            __builtin_prefetch(&in[i + k + 1], 1, 3);
+            int64_t val = in[i + k];
+            sum += val;
+            out[i + k] = sum;
+#if defined(__ARM_NEON)
+            // Distribute to sub-histograms based on chunk index
+            size_t sub = k % SUB_COUNT;
+            sub_hist[sub][val & 255]++;
+#else
+            hist[val & 255]++;
+#endif
+        }
     }
+#if defined(__ARM_NEON)
+    // Merge sub-histograms into final hist
+    for (size_t s = 0; s < SUB_COUNT; ++s) {
+        for (int b = 0; b < 256; ++b) {
+            hist[b] += sub_hist[s][b];
+        }
+    }
+#endif
 }
